<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class RouteCashSettlementVarianceResolution extends Model { protected $fillable=['variance_id','business_id','branch_id','type','amount','cash_register_session_id','cash_movement_id','counterparty_user_id','recorded_by','occurred_at','note','operation_idempotency_key_id']; protected $casts=['amount'=>'decimal:2','occurred_at'=>'datetime']; public function variance(){return $this->belongsTo(RouteCashSettlementVariance::class,'variance_id');} public function cashMovement(){return $this->belongsTo(CashMovement::class,'cash_movement_id');} public function counterparty(){return $this->belongsTo(User::class,'counterparty_user_id');} public function recorder(){return $this->belongsTo(User::class,'recorded_by');} }
